import numpy as np
import pandas as pd

# Test 1: uint64 value 2**63 (just above int64 max)
# Expected (fixed): raises OutOfBoundsDatetime
# Buggy: silently wraps to negative year or NaT
try:
    result = pd.arrays.PeriodArray._from_sequence(np.array([2**63], dtype=np.uint64), dtype='period[D]')
    if pd.isna(result[0]):
        probe('uint64_2_63_is_nat', 1)
    else:
        probe('uint64_2_63_year', result[0].year)
except Exception as e:
    error_msg = str(e)
    if 'OutOfBoundsDatetime' in error_msg or 'overflows' in error_msg:
        probe('uint64_2_63_raised_outofbounds', 1)
    else:
        probe('uint64_2_63_other_error', error_msg)

# Test 2: uint64 value 2**64 - 5
# Expected (fixed): raises OutOfBoundsDatetime
# Buggy: silently wraps
try:
    result = pd.arrays.PeriodArray._from_sequence(np.array([2**64 - 5], dtype=np.uint64), dtype='period[D]')
    if pd.isna(result[0]):
        probe('uint64_2_64_minus_5_is_nat', 1)
    else:
        probe('uint64_2_64_minus_5_year', result[0].year)
except Exception as e:
    error_msg = str(e)
    if 'OutOfBoundsDatetime' in error_msg or 'overflows' in error_msg:
        probe('uint64_2_64_minus_5_raised_outofbounds', 1)
    else:
        probe('uint64_2_64_minus_5_other_error', error_msg)

# Test 3: int64 value 10**18
# Expected (fixed): raises OutOfBoundsDatetime (same error as Period(str(10**18), freq='Y'))
# Buggy: silently wraps
try:
    result = pd.PeriodIndex(np.array([10**18], dtype=np.int64), freq='Y')
    if pd.isna(result[0]):
        probe('int64_10_18_is_nat', 1)
    else:
        probe('int64_10_18_year', result[0].year)
except Exception as e:
    error_msg = str(e)
    if 'OutOfBoundsDatetime' in error_msg or 'overflows' in error_msg:
        probe('int64_10_18_raised_outofbounds', 1)
    else:
        probe('int64_10_18_other_error', error_msg)

# Test 4: Scalar Period(str(10**18), freq='Y') for comparison
try:
    result = pd.Period(str(10**18), freq='Y')
    probe('period_str_10_18_year', result.year)
except Exception as e:
    error_msg = str(e)
    probe('period_str_10_18_error', error_msg)

